#include <filesystem>
std::string real(double value, int digits) {
    std::ostringstream out;
    out << std::fixed << std::setprecision(digits) << value;
    std::string text = out.str();
    if (text[0] == '-' && text.find_first_not_of("0.", 1) == std::string::npos)
        text.erase(text.begin());
    return text;
}
std::string time_text(int milliseconds) {
    std::ostringstream out;
    out << milliseconds / 1000 << '.' << std::setfill('0') << std::setw(3) << milliseconds % 1000;
    return out.str();
}
int hottest(const Field &field) {
    return int(std::max_element(field.begin(), field.end()) - field.begin());
}
std::string summary(const std::string &prefix, const Mesh &mesh, const Field &field) {
    const int p = hottest(field);
    return prefix + " max " + real(field[p], 2) + " at " + mesh.coordinates(p) + " min " +
           real(*std::min_element(field.begin(), field.end()), 2) + " mean " +
           real(std::accumulate(field.begin(), field.end(), 0.0) / mesh.count, 2);
}
void field_lines(Lines &lines, const Mesh &mesh, const Field &field) {
    for (int r = 0; r < mesh.height; ++r) {
        std::string row;
        for (int c = 0; c < mesh.width; ++c) {
            if (c)
                row += ' ';
            row += real(field[mesh.cell(r, c)], 2);
        }
        lines.push_back(row);
    }
}
void isotherms(Lines &lines, const std::string &prefix, const Mesh &mesh, const Field &field,
               const Field &bands) {
    std::vector<int> counts(bands.size() + 1), digits(field.size());
    for (int p = 0; p < mesh.count; ++p) {
        for (double boundary : bands)
            digits[p] += boundary <= field[p];
        ++counts[digits[p]];
    }
    std::string heading = prefix + " counts";
    for (int count : counts)
        heading += " " + std::to_string(count);
    lines.push_back(heading);
    const int peak = hottest(field);
    for (int r = 0; r < mesh.height; ++r) {
        std::string row;
        for (int c = 0; c < mesh.width; ++c) {
            int p = mesh.cell(r, c);
            row += p == peak ? '*' : char('0' + digits[p]);
        }
        lines.push_back(row);
    }
}
void save(const std::string &name, const Lines &lines) {
    std::filesystem::create_directories("output");
    std::ofstream output("output/" + name);
    for (const std::string &line : lines)
        output << line << '\n';
}

#include "heat.hpp"
double g_value(const System &system, const Field &field, int point) {
    double value = 0;
    for (const Face &face : system.faces[point]) {
        if (face.neighbor >= 0)
            value += face.g * field[face.neighbor];
        else if (face.theta)
            value += face.g * *face.theta;
    }
    return value + system.source_all[point];
}
Iteration iterate(const System &system, const Params &params, const std::string &method,
                  double omega) {
    Iteration out{method, Field(system.mesh.count, params.initial), {}, omega, false};
    for (int iteration = 1; iteration <= params.max_iterations; ++iteration) {
        const Field previous = out.field;
        for (int p = 0; p < system.mesh.count; ++p) {
            const double value =
                g_value(system, method == "jacobi" ? previous : out.field, p) / system.diagonal[p];
            if (method == "jacobi" || method == "gauss_seidel")
                out.field[p] = value;
            else
                out.field[p] = out.field[p] + omega * (value - out.field[p]);
        }
        double change = 0;
        for (int p = 0; p < system.mesh.count; ++p)
            change = std::max(change, std::abs(out.field[p] - previous[p]));
        out.changes.push_back(change);
        if (change < params.tolerance) {
            out.converged = true;
            break;
        }
    }
    return out;
}
std::vector<Field> direct(const System &system, std::vector<Field> rhs) {
    const int n = system.mesh.count, w = system.mesh.width;
    std::vector<Field> matrix(n, Field(2 * w + 1));
    auto at = [&](int row, int column) -> double & { return matrix[row][column - row + w]; };
    for (int p = 0; p < n; ++p) {
        at(p, p) = system.diagonal[p];
        for (const Face &face : system.faces[p])
            if (face.neighbor >= 0)
                at(p, face.neighbor) = -face.g;
    }
    for (int k = 0; k < n; ++k) {
        const int stop = std::min(n, k + w + 1);
        for (int i = k + 1; i < stop; ++i) {
            const double factor = at(i, k) / at(k, k);
            at(i, k) = 0;
            for (int j = k + 1; j < stop; ++j)
                at(i, j) = at(i, j) - factor * at(k, j);
            for (Field &values : rhs)
                values[i] = values[i] - factor * values[k];
        }
    }
    std::vector<Field> solutions;
    for (const Field &values : rhs) {
        Field solution(n);
        for (int i = n - 1; i >= 0; --i) {
            double value = values[i];
            for (int j = i + 1; j < std::min(n, i + w + 1); ++j)
                value = value - at(i, j) * solution[j];
            solution[i] = value / at(i, i);
        }
        solutions.push_back(std::move(solution));
    }
    return solutions;
}
double residual(const System &system, const Field &field, const Field &rhs) {
    double maximum = 0;
    for (int p = 0; p < system.mesh.count; ++p) {
        double value = rhs[p];
        for (const Face &face : system.faces[p])
            if (face.neighbor >= 0)
                value += face.g * field[face.neighbor];
        value -= system.diagonal[p] * field[p];
        maximum = std::max(maximum, std::abs(value));
    }
    return maximum;
}

#include "heat.hpp"
double heat_flow(const System &system, const Field &field, int point, int first, int last) {
    double out = 0;
    for (int direction = first; direction < last; ++direction) {
        const Face &face = system.faces[point][direction];
        if (face.neighbor >= 0)
            out += face.g * (field[face.neighbor] - field[point]);
        else if (face.theta)
            out += face.g * (*face.theta - field[point]);
    }
    return out;
}
Field thomas(const Field &lower, const Field &diagonal, const Field &upper, const Field &rhs) {
    const int n = int(rhs.size());
    Field u(n), r(n), out(n);
    u[0] = upper[0] / diagonal[0];
    r[0] = rhs[0] / diagonal[0];
    for (int i = 1; i < n; ++i) {
        const double pivot = diagonal[i] - lower[i] * u[i - 1];
        u[i] = upper[i] / pivot;
        r[i] = (rhs[i] - lower[i] * r[i - 1]) / pivot;
    }
    out[n - 1] = r[n - 1];
    for (int i = n - 2; i >= 0; --i)
        out[i] = r[i] - u[i] * out[i + 1];
    return out;
}
Field sweep(const System &system, double tau, const Field &rhs, bool horizontal) {
    const Mesh &mesh = system.mesh;
    const int count = horizontal ? mesh.height : mesh.width,
              length = horizontal ? mesh.width : mesh.height, first = horizontal ? 0 : 2;
    Field out(mesh.count), lower(length), diagonal(length), upper(length), r(length);
    for (int line = 0; line < count; ++line) {
        for (int i = 0; i < length; ++i) {
            const int p = horizontal ? mesh.cell(line, i) : mesh.cell(i, line);
            const Face &a = system.faces[p][first], &b = system.faces[p][first + 1];
            lower[i] = a.neighbor >= 0 ? -a.g : 0;
            diagonal[i] = system.capacity[p] / tau + a.g + b.g;
            upper[i] = b.neighbor >= 0 ? -b.g : 0;
            r[i] = rhs[p];
            if (a.theta)
                r[i] += a.g * *a.theta;
            if (b.theta)
                r[i] += b.g * *b.theta;
        }
        const Field solved = thomas(lower, diagonal, upper, r);
        for (int i = 0; i < length; ++i)
            out[horizontal ? mesh.cell(line, i) : mesh.cell(i, line)] = solved[i];
    }
    return out;
}
Step advance(const System &system, const Field &field, const Field &source, double dt,
             const std::string &method) {
    const int n = system.mesh.count;
    Step out;
    out.field.resize(n);
    if (method == "ftcs") {
        for (int p = 0; p < n; ++p)
            out.field[p] = field[p] + dt * (heat_flow(system, field, p, 0, 4) + source[p]) /
                                          system.capacity[p];
        return out;
    }
    const bool backward = method == "backward_euler";
    const double tau = backward ? dt : dt / 2;
    Field vertical(n), rhs(n);
    for (int p = 0; p < n; ++p) {
        vertical[p] = heat_flow(system, field, p, 2, 4);
        rhs[p] = system.capacity[p] / tau * field[p] + vertical[p] + source[p];
    }
    out.intermediate = sweep(system, tau, rhs, true);
    for (int p = 0; p < n; ++p)
        rhs[p] = backward ? system.capacity[p] / tau * out.intermediate[p] - vertical[p]
                          : system.capacity[p] / tau * out.intermediate[p] +
                                heat_flow(system, out.intermediate, p, 0, 2) + source[p];
    out.field = sweep(system, tau, rhs, false);
    return out;
}
